2	 * Objective Independent Review Boundary (Nexus Code v1.1.2)
3	 *
4	 * Mitigates common-mode failure and confirmation bias in multi-agent workflows.
5	 * The independent reviewer receives an objective evidence package containing:
6	 * - Original task requirements and acceptance criteria
7	 * - Authorized scope (files permitted to be modified)
8	 * - Repository baseline and candidate diff
9	 * - Deterministic verifier receipts (exit code, raw logs)
10	 *
11	 * CRITICAL INVARIANT: The implementer's narrative ("I fixed this and verified it works")
12	 * is strictly stripped from the evidence package to prevent confirmation bias.
13	 *
14	 * Internal model metrics may veto an implementation, but deterministic verification
15	 * gates remain the authoritative ground truth for completion.
16	 */
17	
18	export interface ReviewEvidencePackage {
19	  operationId: string;
20	  unitId: string;
21	  objective: string;
22	  authorizedScope: readonly string[];
23	  baselineCommit: string;
24	  candidateCommit?: string;
25	  unifiedDiff: string;
26	  verifierCommand?: string;
27	  verifierOutput?: string;
28	  verifierExitCode?: number;
29	  unresolvedAssumptions?: readonly string[];
30	}
31	
32	export interface ReviewDefect {
33	  path: string;
34	  line?: number;
35	  description: string;
36	}
37	
38	export interface IndependentReviewVerdict {
39	  verdict: "ACCEPT" | "REJECT";
40	  verifiedObservations: string[];
41	  suspectedDefects: ReviewDefect[];
42	  unprovenCriteria: string[];
43	  scopeViolations: string[];
44	  reviewerConfidenceNote: string;
45	}
