127	/**
128	 * Formats the review prompt, instructing the independent model to evaluate
129	 * only the objective evidence package and emit a strict JSON verdict.
130	 */
131	export function formatIndependentReviewPrompt(
132	  pkg: ReviewEvidencePackage,
133	): string {
134	  const scopeViolations = detectScopeViolations(pkg.unifiedDiff, pkg.authorizedScope);
135	  const scopeWarning = scopeViolations.length
136	    ? `\n[AUTOMATED SCOPE WARNING] The diff touches files outside authorizedScope: [${scopeViolations.join(", ")}]\n`
137	    : "";
138	
139	  return `[Independent Review Task for Unit '${pkg.unitId}' in Operation '${pkg.operationId}']
140	
141	Objective Requirements:
142	${pkg.objective}
143	
144	Authorized Scope:
145	${pkg.authorizedScope.length ? pkg.authorizedScope.map((s) => `- ${s}`).join("\n") : "Unrestricted (Repository-wide)"}
146	${scopeWarning}
147	Repository Baseline:
148	- Base Commit: ${pkg.baselineCommit}${pkg.candidateCommit ? `\n- Candidate Commit: ${pkg.candidateCommit}` : ""}
149	
150	Verifier Execution Evidence:
151	- Command: ${pkg.verifierCommand ?? "None"}
152	- Exit Code: ${pkg.verifierExitCode !== undefined ? pkg.verifierExitCode : "Untested"}
153	- Raw Verifier Output:
154	\`\`\`
155	${(pkg.verifierOutput ?? "No verifier output recorded").slice(0, 10000)}
156	\`\`\`
157	
158	Candidate Unified Diff:
159	\`\`\`diff
160	${pkg.unifiedDiff.slice(0, 20000)}
161	\`\`\`
162	
163	INSTRUCTIONS FOR INDEPENDENT REVIEWER:
164	1. Do not assume the implementation is correct. The implementer's self-assessed narrative has been excluded.
165	2. Evaluate the code diff against the objective requirements and authorized scope.
166	3. Check for regressions, unhandled edge cases, security boundaries, and incomplete logic.
167	4. You MUST respond with a JSON block adhering strictly to this schema:
168	\`\`\`json
169	{
170	  "verdict": "ACCEPT" | "REJECT",
171	  "verifiedObservations": ["string"],
172	  "suspectedDefects": [{"path": "string", "line": 0, "description": "string"}],
173	  "unprovenCriteria": ["string"],
