181	/**
182	 * Parses and validates an independent reviewer verdict.
183	 * Fails closed as "REJECT" if parsing fails or critical schema invariants are violated.
184	 */
185	export function parseIndependentReviewVerdict(
186	  rawText: string,
187	  pkg?: ReviewEvidencePackage,
188	): IndependentReviewVerdict {
189	  try {
190	    const jsonMatch = rawText.match(/```(?:json)?\s*([\s\S]*?)\s*```/) || [null, rawText];
191	    const candidate = jsonMatch[1] ? jsonMatch[1].trim() : rawText.trim();
192	    const parsed = JSON.parse(candidate);
193	
194	    if (!parsed || typeof parsed !== "object") {
195	      throw new Error("Verdict is not a JSON object");
196	    }
197	
198	    const verdict: "ACCEPT" | "REJECT" = parsed.verdict === "ACCEPT" ? "ACCEPT" : "REJECT";
199	    const verifiedObservations = Array.isArray(parsed.verifiedObservations)
200	      ? parsed.verifiedObservations.map(String)
201	      : [];
202	    const unprovenCriteria = Array.isArray(parsed.unprovenCriteria)
203	      ? parsed.unprovenCriteria.map(String)
204	      : [];
205	    const scopeViolations = Array.isArray(parsed.scopeViolations)
206	      ? parsed.scopeViolations.map(String)
207	      : [];
208	
209	    const suspectedDefects: ReviewDefect[] = [];
210	    if (Array.isArray(parsed.suspectedDefects)) {
211	      for (const d of parsed.suspectedDefects) {
212	        if (d && typeof d === "object" && typeof d.path === "string" && typeof d.description === "string") {
213	          suspectedDefects.push({
214	            path: d.path,
215	            line: typeof d.line === "number" ? d.line : undefined,
216	            description: d.description,
217	          });
218	        }
219	      }
220	    }
221	
222	    // Deterministic gate enforcement: If verifier explicitly failed (exitCode !== 0)
223	    // or deterministic scope violations exist, model ACCEPT cannot override objective failure.
224	    let finalVerdict = verdict;
225	    if (pkg) {
226	      const autoViolations = detectScopeViolations(pkg.unifiedDiff, pkg.authorizedScope);
227	      for (const v of autoViolations) {
228	        if (!scopeViolations.includes(v)) scopeViolations.push(v);
229	      }
230	      if (pkg.verifierExitCode !== undefined && pkg.verifierExitCode !== 0) {
231	        finalVerdict = "REJECT";
232	        unprovenCriteria.push(`Deterministic verifier failed with exit code ${pkg.verifierExitCode}`);
233	      }
234	      if (scopeViolations.length > 0) {
235	        finalVerdict = "REJECT";
236	      }
237	    }
238	
239	    if (suspectedDefects.length > 0) {
240	      finalVerdict = "REJECT";
241	    }
242	
243	    return {
244	      verdict: finalVerdict,
245	      verifiedObservations,
246	      suspectedDefects,
247	      unprovenCriteria,
248	      scopeViolations,
249	      reviewerConfidenceNote: typeof parsed.reviewerConfidenceNote === "string"
250	        ? parsed.reviewerConfidenceNote
251	        : "Automated parsed verdict",
252	    };
253	  } catch (err) {
254	    // Fail-closed as REJECT on any parse failure
255	    return {
256	      verdict: "REJECT",
257	      verifiedObservations: [],
258	      suspectedDefects: [
259	        {
260	          path: "review_verdict.json",
261	          description: `Failed to parse structured review verdict: ${err instanceof Error ? err.message : String(err)}`,
262	        },
263	      ],
264	      unprovenCriteria: ["Structured review verdict validation"],
265	      scopeViolations: [],
266	      reviewerConfidenceNote: "Parser failure: default fail-closed REJECT",
267	    };
268	  }
269	}
