54	/**
55	 * Normalizes error messages and traces by stripping variable memory addresses and line numbers
56	 * to produce a stable hash of the underlying defect.
57	 */
58	function normalizeErrorMessage(msg: string): string {
59	  return msg
60	    .replace(/at (?:[^\s]+) \((?:.+):(\d+):(\d+)\)/g, "at $1")
61	    .replace(/0x[0-9a-fA-F]+/g, "0xHEX")
62	    .replace(/\s+/g, " ")
63	    .trim();
64	}
