66	/**
67	 * Computes a deterministic SHA-256 fingerprint for a failure event.
68	 */
69	export function computeFailureFingerprint(evidence: FailureEvidence): string {
70	  const normStderr = evidence.stderr ? normalizeErrorMessage(evidence.stderr) : "";
71	  const failingTests = (evidence.failingTests ?? []).slice().sort().join(",");
72	  const payload = `exit=${evidence.exitCode}|tests=${failingTests}|stderr=${normStderr}`;
73	  return createHash("sha256").update(payload).digest("hex").slice(0, 16);
74	}
