76	/**
77	 * Computes a hash of the current code diff to identify unchanged or thrashing edits.
78	 */
79	export function computeDiffHash(diff?: string): string {
80	  if (!diff) return "no_diff";
81	  return createHash("sha256").update(diff.trim()).digest("hex").slice(0, 16);
82	}
