89	  const maxAttempts = context.options?.maxAttempts ?? 3;
90	  const currentFingerprint = computeFailureFingerprint(context.failureEvidence);
91	  const currentDiffHash = computeDiffHash(context.failureEvidence.diff);
92	
93	  // Check for cycle detection first: repeated identical failure signature with identical or cycling diff
94	  const matchingFailures = context.history.filter(
95	    (entry) => entry.fingerprint === currentFingerprint
96	  );
97	
98	  const cycleThreshold = context.options?.cycleThreshold ?? 2;
99	  if (matchingFailures.length >= cycleThreshold) {
100	    return {
101	      nextStage: "OPERATOR_DECISION",
102	      cycleDetected: true,
103	      recommendedAction: "REQUEST_OPERATOR",
104	      reason: `Cycle detected: failure fingerprint '${currentFingerprint}' observed ${matchingFailures.length + 1} times. Halting for operator intervention to prevent token thrashing.`,
105	    };
106	  }
107	
108	  // Check for max attempts exceeded
109	  if (context.attemptCount >= maxAttempts) {
110	    return {
111	      nextStage: "OPERATOR_DECISION",
112	      cycleDetected: false,
113	      recommendedAction: "REQUEST_OPERATOR",
114	      reason: `Maximum escalation attempts (${maxAttempts}) exceeded without resolution. Halting for operator decision.`,
115	    };
116	  }
117	
118	  // State transitions
119	  switch (context.currentStage) {
120	    case "INITIAL_ATTEMPT": {
121	      return {
122	        nextStage: "DIAGNOSTIC_ANALYSIS",
123	        targetRole: "failure_debugger",
124	        tokenBudgetMultiplier: 1.0,
125	        cycleDetected: false,
126	        recommendedAction: "RETRY_WITH_SPECIALIST",
127	        reason: "Initial attempt failed verifier checks. Delegating to diagnostic specialist ('failure_debugger') to identify root cause.",
128	      };
129	    }
130	
131	    case "DIAGNOSTIC_ANALYSIS": {
132	      return {
133	        nextStage: "DEEP_REASONING_ESCALATION",
134	        requiredCapability: "reasoning",
135	        tokenBudgetMultiplier: 2.0,
136	        cycleDetected: false,
137	        recommendedAction: "ESCALATE_MODEL",
138	        reason: "Diagnostic analysis did not yield passing verification. Escalating to deep reasoning model with doubled token budget.",
139	      };
140	    }
141	
142	    case "DEEP_REASONING_ESCALATION": {
143	      return {
144	        nextStage: "OPERATOR_DECISION",
145	        cycleDetected: false,
146	        recommendedAction: "REQUEST_OPERATOR",
147	        reason: "Deep reasoning attempt failed to resolve issue. Escalating to operator decision.",
148	      };
149	    }
150	
151	    case "OPERATOR_DECISION":
152	    default: {
153	      return {
154	        nextStage: "OPERATOR_DECISION",
155	        cycleDetected: false,
156	        recommendedAction: "REQUEST_OPERATOR",
157	        reason: "Operation remains halted awaiting operator decision.",
158	      };
159	    }
