1	export interface AdaptiveThrottleOptions {
2	  baselineConcurrency: number;
3	  baselineLatencyMs: number;
4	  minConcurrency?: number;
5	  maxConcurrency?: number;
6	  windowSize?: number;
7	}
8	
9	export interface TelemetryObservation {
10	  latencyMs: number;
11	  ttftMs?: number;
12	  success: boolean;
13	  timeout?: boolean;
14	}
15	
16	export interface ThrottleMetrics {
17	  averageLatencyMs: number;
18	  averageTtftMs: number;
19	  timeoutRate: number;
20	  sampleCount: number;
21	}
22	
23	/**
24	 * Dynamically adjusts available concurrency slots based on rolling latency, TTFT,
25	 * and timeout rates to avoid cascading failures under model or network load.
26	 */
27	export class AdaptiveConcurrencyThrottle {
28	  private readonly baselineConcurrency: number;
29	  private readonly baselineLatencyMs: number;
30	  private readonly minConcurrency: number;
31	  private readonly maxConcurrency: number;
32	  private readonly windowSize: number;
33	  private readonly history: TelemetryObservation[] = [];
34	
35	  constructor(options: AdaptiveThrottleOptions) {
36	    this.baselineConcurrency = Math.max(1, options.baselineConcurrency);
37	    this.baselineLatencyMs = Math.max(1, options.baselineLatencyMs);
38	    this.minConcurrency = Math.max(1, options.minConcurrency ?? 1);
39	    this.maxConcurrency = options.maxConcurrency ?? this.baselineConcurrency;
40	    this.windowSize = Math.max(2, options.windowSize ?? 10);
41	  }
42	
43	  recordObservation(observation: TelemetryObservation): void {
44	    this.history.push({ ...observation });
45	    if (this.history.length > this.windowSize) {
46	      this.history.shift();
47	    }
48	  }
49	
50	  getCurrentLimit(): number {
51	    if (this.history.length === 0) {
52	      return this.baselineConcurrency;
53	    }
54	
55	    const metrics = this.getMetrics();
56	
57	    // If timeout rate exceeds 20%, force to minimum concurrency
58	    if (metrics.timeoutRate >= 0.2) {
59	      return this.minConcurrency;
60	    }
61	
62	    // Ratio of observed latency to baseline latency
63	    const latencyRatio = metrics.averageLatencyMs / this.baselineLatencyMs;
64	
65	    if (latencyRatio <= 1.2) {
66	      // Normal latency
67	      return this.baselineConcurrency;
68	    }
69	
70	    // High latency: scale concurrency down proportionally
71	    const adjusted = Math.floor(this.baselineConcurrency / latencyRatio);
72	    return Math.max(this.minConcurrency, Math.min(this.maxConcurrency, adjusted));
73	  }
74	
75	  isThrottled(): boolean {
76	    return this.getCurrentLimit() < this.baselineConcurrency;
77	  }
78	
79	  getMetrics(): ThrottleMetrics {
80	    if (this.history.length === 0) {
81	      return {
82	        averageLatencyMs: this.baselineLatencyMs,
83	        averageTtftMs: 0,
84	        timeoutRate: 0,
85	        sampleCount: 0,
86	      };
87	    }
88	
89	    let totalLatency = 0;
90	    let totalTtft = 0;
91	    let ttftCount = 0;
92	    let timeouts = 0;
93	
94	    for (const item of this.history) {
95	      totalLatency += item.latencyMs;
96	      if (typeof item.ttftMs === "number") {
97	        totalTtft += item.ttftMs;
98	        ttftCount++;
99	      }
100	      if (item.timeout) {
101	        timeouts++;
102	      }
103	    }
104	
105	    return {
106	      averageLatencyMs: totalLatency / this.history.length,
107	      averageTtftMs: ttftCount > 0 ? totalTtft / ttftCount : 0,
108	      timeoutRate: timeouts / this.history.length,
109	      sampleCount: this.history.length,
110	    };
111	  }
112	}
