114	export type BudgetStatus = "OK" | "WARNING" | "CRITICAL" | "EXHAUSTED";
115	
116	export interface TokenBudgetOptions {
117	  maxTokens: number;
118	  warningThreshold?: number;
119	  criticalThreshold?: number;
120	}
121	
122	/**
123	 * Tracks token consumption against an operation budget, alerting at thresholds
124	 * and rejecting further consumption once exhausted.
125	 */
126	export class TokenBudgetTracker {
127	  private readonly maxTokens: number;
128	  private readonly warningRatio: number;
129	  private readonly criticalRatio: number;
130	  private consumedTokens = 0;
131	
132	  constructor(options: TokenBudgetOptions) {
133	    this.maxTokens = Math.max(1, options.maxTokens);
134	    this.warningRatio = options.warningThreshold ?? 0.8;
135	    this.criticalRatio = options.criticalThreshold ?? 0.95;
136	  }
137	
138	  consume(tokens: number): boolean {
139	    if (tokens < 0) return true;
140	    if (this.consumedTokens + tokens > this.maxTokens) {
141	      return false;
142	    }
143	    this.consumedTokens += tokens;
144	    return true;
145	  }
146	
147	  getRemainingTokens(): number {
148	    return Math.max(0, this.maxTokens - this.consumedTokens);
149	  }
150	
151	  getTotalConsumed(): number {
152	    return this.consumedTokens;
153	  }
154	
155	  isExhausted(): boolean {
156	    return this.consumedTokens >= this.maxTokens;
157	  }
158	
159	  getWarningStatus(): BudgetStatus {
160	    const ratio = this.consumedTokens / this.maxTokens;
161	    if (ratio >= 1.0) return "EXHAUSTED";
162	    if (ratio >= this.criticalRatio) return "CRITICAL";
163	    if (ratio >= this.warningRatio) return "WARNING";
164	    return "OK";
165	  }
166	}
