 14 │ export class CeriEvidenceStore {
 15 │   private readonly baseDir: string;
 16 │   private currentRunDir?: string;
 17 │   private currentManifest?: RunManifest;
 18 │ 
 19 │   constructor(baseDir: string) {
 20 │     this.baseDir = path.resolve(baseDir);
 21 │     if (!fs.existsSync(this.baseDir)) {
 22 │       fs.mkdirSync(this.baseDir, { recursive: true });
 23 │     }
 24 │   }
 25 │ 
 26 │   /**
 27 │    * Initializes a run directory and atomically writes the initial RunManifest.
 28 │    */
 29 │   initRun(manifest: RunManifest): string {
 30 │     const runDir = path.join(this.baseDir, manifest.evaluationId, manifest.runId);
 31 │     fs.mkdirSync(runDir, { recursive: true });
 32 │     this.currentRunDir = runDir;
 33 │     this.currentManifest = { ...manifest, status: "RUNNING" };
 34 │ 
 35 │     const manifestPath = path.join(runDir, "manifest.json");
 36 │     this.atomicWriteJson(manifestPath, this.currentManifest);
 37 │     return runDir;
 38 │   }
 39 │ 
 40 │   /**
 41 │    * Appends an event to events.jsonl with secret redaction.
 42 │    */
 43 │   appendEvent(event: Record<string, unknown>): void {
 44 │     if (!this.currentRunDir) {
 45 │       throw new Error("Cannot append event: no active run initialized");
 46 │     }
 47 │     const eventsPath = path.join(this.currentRunDir, "events.jsonl");
 48 │     const serialized = JSON.stringify(event, (_k, v) => (typeof v === "string" ? redactSecrets(v) : v));
 49 │     fs.appendFileSync(eventsPath, serialized + "\n", { encoding: "utf-8" });
 50 │   }
