 55 │   recordAssertions(assertions: Record<string, unknown>[]): void {
 56 │     if (!this.currentRunDir) {
 57 │       throw new Error("Cannot record assertions: no active run initialized");
 58 │     }
 59 │     const assertionsPath = path.join(this.currentRunDir, "assertions.json");
 60 │     this.atomicWriteJson(assertionsPath, assertions);
 61 │   }
 62 │ 
 63 │   /**
 64 │    * Records independent validation receipts atomically.
 65 │    */
 66 │   recordReceipts(receipts: Record<string, unknown>[]): void {
 67 │     if (!this.currentRunDir) {
 68 │       throw new Error("Cannot record receipts: no active run initialized");
 69 │     }
 70 │     const receiptsPath = path.join(this.currentRunDir, "receipts.json");
 71 │     this.atomicWriteJson(receiptsPath, receipts);
 72 │   }
 73 │ 
 74 │   /**
 75 │    * Finalizes the run, updates status and completedAt in manifest, and generates
 76 │    * a tamper-evident integrity record linking all artifacts.
 77 │    */
 78 │   finalizeRun(status: RunStatus, terminationReason?: string): { integrityHash: string; runDir: string } {
 79 │     if (!this.currentRunDir || !this.currentManifest) {
 80 │       throw new Error("Cannot finalize run: no active run initialized");
 81 │     }
 82 │ 
 83 │     const completedAt = new Date().toISOString();
 84 │     const durationMs = Date.now() - new Date(this.currentManifest.startedAt).getTime();
 85 │ 
 86 │     this.currentManifest.status = status;
 87 │     this.currentManifest.completedAt = completedAt;
 88 │     this.currentManifest.durationMs = durationMs;
 89 │     if (terminationReason) {
 90 │       this.currentManifest.terminationReason = terminationReason;
 91 │     }
 92 │ 
 93 │     const manifestPath = path.join(this.currentRunDir, "manifest.json");
 94 │     this.atomicWriteJson(manifestPath, this.currentManifest);
 95 │ 
 96 │     // Compute file hashes for tamper evidence
 97 │     const files = fs.readdirSync(this.currentRunDir).filter((f) => f !== "integrity.json" && !f.startsWith(".tmp"));
 98 │     const fileHashes: Record<string, string> = {};
 99 │     const compositeHasher = createHash("sha256");
100 │ 
101 │     files.sort().forEach((file) => {
102 │       const fullPath = path.join(this.currentRunDir!, file);
103 │       const content = fs.readFileSync(fullPath);
104 │       const hash = createHash("sha256").update(content).digest("hex");
105 │       fileHashes[file] = hash;
106 │       compositeHasher.update(`${file}:${hash};`);
107 │     });
108 │ 
109 │     const compositeSha256 = compositeHasher.digest("hex");
110 │     const integrityRecord: IntegrityRecord = {
111 │       runId: this.currentManifest.runId,
112 │       calculatedAt: completedAt,
113 │       fileHashes,
114 │       compositeSha256,
115 │     };
116 │ 
117 │     const integrityPath = path.join(this.currentRunDir, "integrity.json");
118 │     this.atomicWriteJson(integrityPath, integrityRecord);
119 │ 
120 │     const result = { integrityHash: compositeSha256, runDir: this.currentRunDir };
121 │     this.currentRunDir = undefined;
122 │     this.currentManifest = undefined;
123 │     return result;
124 │   }
125 │ 
126 │   /**
127 │    * Scans baseDir for runs left in RUNNING status without completion (interrupted runs).
128 │    */
129 │   detectInterruptedRuns(): string[] {
130 │     const interrupted: string[] = [];
131 │     if (!fs.existsSync(this.baseDir)) return interrupted;
132 │ 
133 │     const evalDirs = fs.readdirSync(this.baseDir);
134 │     for (const evalId of evalDirs) {
135 │       const evalPath = path.join(this.baseDir, evalId);
136 │       if (!fs.statSync(evalPath).isDirectory()) continue;
137 │ 
138 │       const runDirs = fs.readdirSync(evalPath);
139 │       for (const runId of runDirs) {
140 │         const runPath = path.join(evalPath, runId);
141 │         if (!fs.statSync(runPath).isDirectory()) continue;
142 │ 
143 │         const manifestPath = path.join(runPath, "manifest.json");
144 │         if (fs.existsSync(manifestPath)) {
145 │           try {
146 │             const manifest = JSON.parse(fs.readFileSync(manifestPath, "utf-8")) as RunManifest;
147 │             if (manifest.status === "RUNNING" && !manifest.completedAt) {
148 │               interrupted.push(manifest.runId);
