  8 │ export class CeriBaselineComparator {
  9 │   /**
 10 │    * Checks whether a run is eligible for direct comparison against a designated baseline.
 11 │    */
 12 │   static checkComparability(
 13 │     manifest: RunManifest,
 14 │     baseline: BaselineSpecification
 15 │   ): { eligible: boolean; reasons: string[] } {
 16 │     const reasons: string[] = [];
 17 │ 
 18 │     if (manifest.evaluationId !== baseline.evaluationId) {
 19 │       reasons.push(
 20 │         `Evaluation ID mismatch: current '${manifest.evaluationId}' vs baseline '${baseline.evaluationId}'`
 21 │       );
 22 │     }
 23 │ 
 24 │     if (manifest.evaluationVersion !== baseline.evaluationVersion) {
 25 │       reasons.push(
 26 │         `Evaluation definition version drift: current '${manifest.evaluationVersion}' vs baseline '${baseline.evaluationVersion}'`
 27 │       );
 28 │     }
 29 │ 
 30 │     if (manifest.model.name !== baseline.modelName) {
 31 │       reasons.push(
 32 │         `Model mismatch: current '${manifest.model.name}' vs baseline '${baseline.modelName}'`
 33 │       );
 34 │     }
 35 │ 
 36 │     if (
 37 │       baseline.modelQuantization &&
 38 │       manifest.model.quantization &&
 39 │       manifest.model.quantization !== baseline.modelQuantization
 40 │     ) {
 41 │       reasons.push(
 42 │         `Model quantization mismatch: current '${manifest.model.quantization}' vs baseline '${baseline.modelQuantization}'`
 43 │       );
 44 │     }
 45 │ 
 46 │     if (manifest.dirtyWorktree) {
 47 │       reasons.push("Current run was executed on an uncommitted / dirty worktree");
 48 │     }
 49 │ 
 50 │     return {
 51 │       eligible: reasons.length === 0,
 52 │       reasons,
 53 │     };
 54 │   }
 55 │ 
 56 │   /**
 57 │    * Evaluates current run assertions against baseline assertions and classifies the comparative outcome
 58 │    * into one of 12 distinct deterministic states.
 59 │    */
 60 │   static compareRuns(
 61 │     manifest: RunManifest,
 62 │     currentAssertions: Record<string, boolean>,
 63 │     baseline: BaselineSpecification,
 64 │     baselineAssertions: Record<string, boolean>,
 65 │     isRepeatReproduction = false
 66 │   ): BaselineComparisonResult {
 67 │     // 1. Check basic execution statuses
 68 │     if (manifest.status === "CANCELLED") {
 69 │       return {
 70 │         baselineId: baseline.baselineId,
 71 │         currentRunId: manifest.runId,
 72 │         isEligibleForComparison: false,
 73 │         outcome: "CANCELLED",
 74 │         divergences: [],
 75 │         confidence: 1.0,
 76 │         explanation: "Run was cancelled by operator before completion.",
 77 │       };
 78 │     }
 79 │ 
 80 │     if (manifest.status === "INTERRUPTED") {
 81 │       return {
 82 │         baselineId: baseline.baselineId,
 83 │         currentRunId: manifest.runId,
 84 │         isEligibleForComparison: false,
 85 │         outcome: "INCONCLUSIVE",
 86 │         divergences: [],
 87 │         confidence: 0.0,
 88 │         explanation: "Run was interrupted before assertions could be finalized.",
 89 │       };
 90 │     }
 91 │ 
 92 │     // 2. Check baseline comparability
 93 │     const comp = this.checkComparability(manifest, baseline);
 94 │     if (!comp.eligible) {
 95 │       return {
 96 │         baselineId: baseline.baselineId,
 97 │         currentRunId: manifest.runId,
 98 │         isEligibleForComparison: false,
 99 │         incomparabilityReasons: comp.reasons,
100 │         outcome: "INCOMPARABLE",
101 │         divergences: [],
102 │         confidence: 0.0,
103 │         explanation: `Incomparable configurations: ${comp.reasons.join("; ")}`,
104 │       };
105 │     }
106 │ 
107 │     // 3. Compare assertions
108 │     const allAssertionIds = Array.from(
109 │       new Set([...Object.keys(currentAssertions), ...Object.keys(baselineAssertions)])
110 │     );
111 │ 
112 │     const divergences: BaselineComparisonResult["divergences"] = [];
113 │     let hasRegression = false;
114 │     let hasImprovement = false;
115 │     let allCurrentPassed = true;
116 │     let allBaselinePassed = true;
117 │ 
118 │     for (const id of allAssertionIds) {
119 │       const cur = currentAssertions[id] ?? false;
120 │       const base = baselineAssertions[id] ?? false;
121 │ 
122 │       if (!cur) allCurrentPassed = false;
123 │       if (!base) allBaselinePassed = false;
124 │ 
125 │       if (base === true && cur === false) {
126 │         hasRegression = true;
127 │         divergences.push({
128 │           assertionId: id,
129 │           baselineStatus: "PASS",
130 │           currentStatus: "FAIL",
131 │           details: `Assertion '${id}' passed in baseline but failed in current run.`,
132 │         });
133 │       } else if (base === false && cur === true) {
134 │         hasImprovement = true;
135 │         divergences.push({
136 │           assertionId: id,
137 │           baselineStatus: "FAIL",
138 │           currentStatus: "PASS",
139 │           details: `Assertion '${id}' failed in baseline but passed in current run.`,
140 │         });
141 │       }
142 │     }
143 │ 
144 │     // 4. Determine comparative classification
145 │     let outcome: ComparativeOutcome;
146 │     let explanation: string;
147 │ 
148 │     if (hasRegression) {
149 │       if (isRepeatReproduction) {
150 │         outcome = "CONFIRMED_REGRESSION";
151 │         explanation = `Confirmed reproducible regression across ${divergences.length} assertion(s).`;
152 │       } else {
153 │         outcome = "REGRESSION_CANDIDATE";
154 │         explanation = `Regression candidate detected across ${divergences.length} assertion(s). Requires reproduction run.`;
155 │       }
156 │     } else if (hasImprovement) {
157 │       outcome = "IMPROVEMENT_CANDIDATE";
158 │       explanation = `Improvement candidate: ${divergences.length} previously failing assertion(s) now pass.`;
159 │     } else if (allCurrentPassed && allBaselinePassed) {
160 │       outcome = "PASS";
161 │       explanation = "All deterministic assertions pass and match baseline behavior.";
162 │     } else {
163 │       outcome = "FAIL";
164 │       explanation = "Current run failed assertions in identical manner to baseline.";
165 │     }
166 │ 
167 │     return {
168 │       baselineId: baseline.baselineId,
169 │       currentRunId: manifest.runId,
170 │       isEligibleForComparison: true,
171 │       outcome,
172 │       divergences,
173 │       confidence: 1.0,
174 │       explanation,
175 │     };
176 │   }
177 │ }

