  3 │ export class CeriReportGenerator {
  4 │   /**
  5 │    * Generates a structured operational report from executed evaluation runs and baseline comparisons.
  6 │    */
  7 │   static generateOperationalReport(
  8 │     runs: Array<{ manifest: RunManifest; comparison?: BaselineComparisonResult }>,
  9 │     totalAvailableEvaluations: number,
 10 │     options?: {
 11 │       baselineId?: string;
 12 │       limitations?: string[];
 13 │     }
 14 │   ): CeriOperationalReport {
 15 │     let passedRuns = 0;
 16 │     let failedRuns = 0;
 17 │     let inconclusiveCount = 0;
 18 │     let flakyCount = 0;
 19 │     let infrastructureFailures = 0;
 20 │     const confirmedRegressions: string[] = [];
 21 │     const regressionCandidates: string[] = [];
 22 │     const blockers: string[] = [];
 23 │ 
 24 │     for (const { manifest, comparison } of runs) {
 25 │       if (manifest.status === "FAILED") failedRuns++;
 26 │       else if (manifest.status === "COMPLETED") passedRuns++;
 27 │       else if (manifest.status === "INTERRUPTED") inconclusiveCount++;
 28 │ 
 29 │       if (comparison) {
 30 │         if (comparison.outcome === "CONFIRMED_REGRESSION") {
 31 │           confirmedRegressions.push(comparison.currentRunId);
 32 │           blockers.push(`Confirmed regression in evaluation '${manifest.evaluationId}' (Run ${manifest.runId})`);
 33 │         } else if (comparison.outcome === "REGRESSION_CANDIDATE") {
 34 │           regressionCandidates.push(comparison.currentRunId);
 35 │         } else if (comparison.outcome === "FLAKY") {
 36 │           flakyCount++;
 37 │         } else if (comparison.outcome === "INFRASTRUCTURE_FAILURE") {
 38 │           infrastructureFailures++;
 39 │         } else if (comparison.outcome === "INCONCLUSIVE") {
 40 │           inconclusiveCount++;
 41 │         }
 42 │       }
 43 │     }
 44 │ 
 45 │     const executedRuns = runs.length;
 46 │     const completenessScore =
 47 │       executedRuns > 0 ? Number(((executedRuns / Math.max(1, totalAvailableEvaluations)) * 100).toFixed(1)) : 0;
 48 │ 
 49 │     return {
 50 │       reportId: `CERI-REP-${Date.now()}`,
 51 │       generatedAt: new Date().toISOString(),
 52 │       evaluationCoverage: {
 53 │         totalEvaluations: totalAvailableEvaluations,
 54 │         executedRuns,
 55 │         passedRuns,
 56 │         failedRuns,
 57 │       },
 58 │       baselineId: options?.baselineId,
 59 │       regressions: {
 60 │         confirmed: confirmedRegressions,
 61 │         candidates: regressionCandidates,
 62 │       },
 63 │       inconclusiveCount,
 64 │       flakyCount,
 65 │       infrastructureFailures,
 66 │       blockers,
 67 │       evidenceCompletenessScore: completenessScore,
 68 │       limitations: options?.limitations ?? [
 69 │         "Internal evaluation results serve as release veto gates; independent verification receipts required for certification.",
 70 │       ],
 71 │     };
 72 │   }
 73 │ 
 74 │   /**
 75 │    * Formats the operational report as a clean GitHub-style Markdown report.
 76 │    */
 77 │   static formatMarkdownReport(report: CeriOperationalReport): string {
 78 │     const lines: string[] = [];
 79 │     lines.push(`# Continuous Evaluation and Regression Intelligence (CERI) Report`);
 80 │     lines.push(`**Report ID:** \`${report.reportId}\`  `);
 81 │     lines.push(`**Generated At:** ${report.generatedAt}  `);
 82 │     if (report.baselineId) {
 83 │       lines.push(`**Designated Baseline:** \`${report.baselineId}\`  `);
 84 │     }
 85 │     lines.push(`**Coverage Score:** ${report.evidenceCompletenessScore}% (${report.evaluationCoverage.executedRuns}/${report.evaluationCoverage.totalEvaluations} evaluations executed)  `);
 86 │     lines.push("");
 87 │ 
 88 │     lines.push(`## 1. Executive Status & Release Gates`);
 89 │     if (report.blockers.length > 0) {
 90 │       lines.push(`> [!CAUTION]`);
 91 │       lines.push(`> **RELEASE BLOCKED:** ${report.blockers.length} confirmed regression blocker(s) detected.`);
 92 │       for (const b of report.blockers) {
 93 │         lines.push(`> - ${b}`);
 94 │       }
 95 │     } else if (report.regressions.candidates.length > 0) {
 96 │       lines.push(`> [!WARNING]`);
 97 │       lines.push(`> **QUALIFICATION IN PROGRESS:** ${report.regressions.candidates.length} regression candidate(s) awaiting reproduction runs.`);
 98 │     } else {
 99 │       lines.push(`> [!NOTE]`);
100 │       lines.push(`> **NO REGRESSIONS OBSERVED:** All executed evaluations match or exceed baseline criteria.`);
101 │     }
102 │     lines.push("");
103 │ 
104 │     lines.push(`## 2. Evaluation Metrics Ledger`);
105 │     lines.push(`| Metric | Value |`);
106 │     lines.push(`|---|---|`);
107 │     lines.push(`| Executed Runs | ${report.evaluationCoverage.executedRuns} |`);
108 │     lines.push(`| Passed Runs | ${report.evaluationCoverage.passedRuns} |`);
109 │     lines.push(`| Failed Runs | ${report.evaluationCoverage.failedRuns} |`);
110 │     lines.push(`| Confirmed Regressions | ${report.regressions.confirmed.length} |`);
111 │     lines.push(`| Regression Candidates | ${report.regressions.candidates.length} |`);
112 │     lines.push(`| Inconclusive / Interrupted | ${report.inconclusiveCount} |`);
113 │     lines.push(`| Flaky Evaluations | ${report.flakyCount} |`);
114 │     lines.push(`| Infrastructure Failures | ${report.infrastructureFailures} |`);
115 │     lines.push("");
116 │ 
117 │     lines.push(`## 3. Explicit Measurement Limitations`);
118 │     for (const lim of report.limitations) {
119 │       lines.push(`- ${lim}`);
120 │     }
121 │     lines.push("");
122 │ 
123 │     return lines.join("\n");
124 │   }
125 │ }
