200	/** Output with timestamps, durations, ids, addresses and temporary paths normalized away. */
201	export function normalizeOutcomeText(text: string): string {
202	  let out = text;
203	  for (const [pattern, replacement] of VOLATILE) out = out.replace(pattern, replacement);
204	  return out.replace(/[ \t]+/g, " ").trim();
205	}
206	
207	const TRANSIENT = /\b(ECONNREFUSED|ECONNRESET|ETIMEDOUT|EAI_AGAIN|EHOSTUNREACH|ENETUNREACH|EPIPE|timed? ?out|temporar(?:il)?y unavailable|service unavailable|too many requests|rate[- ]limit(?:ed)?|connection (?:reset|refused|closed)|network is unreachable|could not resolve host|try again|HTTP\/\d(?:\.\d)? (?:429|502|503|504)|\b(?:429|502|503|504) (?:Too Many|Bad Gateway|Service Unavailable|Gateway Time))/i;
208	
209	/**
210	 * A tool that ran but reports a command's failure in its output (run_command answers `success` with a JSON body
211	 * carrying `exit_code` and `timed_out`): the command's own result decides success, not the tool's.
212	 */
213	export function commandResult(success: boolean, text: string): { success: boolean; timedOut: boolean } {
214	  if (!success || !text.trimStart().startsWith("{")) return { success, timedOut: false };
215	  try {
216	    const parsed = JSON.parse(text);
217	    if (parsed && typeof parsed === "object" && typeof parsed.exit_code === "number") {
218	      const timedOut = parsed.timed_out === true;
219	      return { success: parsed.exit_code === 0 && !timedOut, timedOut };
220	    }
221	  } catch {}
222	  return { success, timedOut: false };
223	}
224	
225	export function classifyOutcome(success: boolean, text: string, timedOut = false): OutcomeClass {
226	  if (success) return "success";
227	  return timedOut || TRANSIENT.test(text) ? "transient_failure" : "deterministic_failure";
228	}
229	
230	export function outcomeIdentity(success: boolean, text: string): string {
231	  return digest(`${success ? "ok" : "fail"}\u0000${normalizeOutcomeText(text)}`);
232	}
