234	const WORKSPACE_OBSERVERS = new Set([
235	  "read_file", "batch_read", "list_dir", "file_tree", "find_files", "search_code", "outline_file", "file_info",
236	  "read_findings", "read_objective", "read_archive", "git_status", "git_diff", "git_log", "semantic_search",
237	  "hybrid_search", "symbol_search", "lsp_definition", "lsp_references", "lsp_hover", "lsp_diagnostics",
238	  // A completion attempt's verdict is determined by the workspace: resubmitting on an unchanged one cannot change it.
239	  "task_completed",
240	]);
241	const BOOKKEEPING = new Set(["update_plan", "update_requirements", "enable_tools"]);
242	const MUTATORS = new Set(["write_file", "edit_file", "patch_file", "delete_file", "move_file", "create_dir", "apply_patch", "multi_edit", "write_workspace"]);
243	
244	export function actionKind(name: string): ActionKind {
245	  if (BOOKKEEPING.has(name)) return "bookkeeping";
246	  if (MUTATORS.has(name)) return "mutate";
247	  if (WORKSPACE_OBSERVERS.has(name)) return "observe_workspace";
248	  return "external";
249	}
