251	/** Backoff before re-running an unchanged poll or a transient failure that has occurred `count` times. */
252	export function backoffMs(count: number): number {
253	  if (count < 1) return 0;
254	  return Math.min(BACKOFF_MAX_MS, BACKOFF_BASE_MS * 2 ** (count - 1));
255	}
256	
257	function pushBounded<T>(list: T[], item: T, max: number, onEvict?: (n: number) => void): void {
258	  list.push(item);
259	  if (list.length > max) {
260	    const n = list.length - max;
261	    list.splice(0, n);
262	    onEvict?.(n);
263	  }
264	}
265	
266	function addSeen(list: string[], value: string, onEvict: (n: number) => void): boolean {
267	  if (list.includes(value)) return false;
268	  pushBounded(list, value, MAX_SEEN, onEvict);
269	  return true;
270	}
