272	export interface Observation {
273	  name: string;
274	  args: unknown;
275	  success: boolean;
276	  /** Output on success, error text otherwise (before Nexus adds notes to it). */
277	  text: string;
278	  timedOut?: boolean;
279	  /** State identity before the call ran; "unknown" when it could not be established. */
280	  stateBefore: string;
281	  /** Compaction had removed this call's earlier output from context: running it again re-acquires it. */
282	  reacquire?: boolean;
283	}
