308	/** Mutable view over the ledger's tracking record. */
309	export class ExecutionTracker {
310	  constructor(public readonly data: ExecutionTracking, private readonly clock: () => string = () => new Date().toISOString()) {}
311	
312	  static fresh(): ExecutionTracker {
313	    return new ExecutionTracker(createTracking());
314	  }
315	
316	  private event(list: TrackingEvent[], max: number, step: number, kind: string, detail: string): void {
317	    pushBounded(list, { step, at: this.clock(), kind, detail: clip(detail, 400) }, max, (n) => (this.data.evicted.events += n));
318	  }
319	
320	  beginTurn(): void {
321	    this.data.turns++;
322	  }
323	
324	  beginStep(): number {
325	    return ++this.data.cumulativeSteps;
326	  }
327	
328	  /** Records a single tool result; the verdict says whether it was new, a poll, or part of a demonstrated loop. */
329	  observe(step: number, o: Observation): ObservationVerdict {
330	    const kind = actionKind(o.name);
331	    const command = commandResult(o.success, o.text);
332	    const outcomeClass = classifyOutcome(command.success, o.text, o.timedOut || command.timedOut);
333	    const action = actionIdentity(o.name, o.args);
334	    const outcome = outcomeIdentity(command.success, o.text);
335	    const stateUnknown = o.stateBefore === "unknown";
336	    const actionId = digest(action);
337	    const key = digest(`${action}\u0000${outcome}\u0000${o.stateBefore}`);
338	    let record = this.data.repetitions.find((r) => r.key === key);
339	    const seenBefore = !stateUnknown && this.data.seenObservations.includes(key);
340	    if (!record) {
341	      record = {
342	        key,
343	        action: clip(`${o.name} ${typeof o.args === "string" ? o.args : JSON.stringify(o.args ?? {})}`.replace(/\s+/g, " "), 160),
344	        actionId,
345	        actionKind: kind,
346	        outcomeClass,
347	        state: o.stateBefore,
348	        // Seen before but its record was evicted: the recurrence still counts.
349	        count: seenBefore ? 1 : 0,
350	        firstStep: step,
351	        lastStep: step,
352	        outcome: clip(normalizeOutcomeText(o.text), 240),
353	      };
354	      this.insertRepetition(record);
355	    }
356	    record.count++;
357	    record.lastStep = step;
358	    const reacquired = Boolean(o.reacquire) && record.count > 1;
359	    if (reacquired) record.reacquired = (record.reacquired ?? 0) + 1;
360	    if (!stateUnknown) addSeen(this.data.seenObservations, key, (n) => (this.data.evicted.observations += n));
361	    // On an unknown state no recurrence can be shown to share its input: it is recorded, never judged a repeat.
362	    const repeat = record.count > 1 && !stateUnknown;
363	    const informative = record.count === 1 && kind !== "bookkeeping" && kind !== "mutate" && outcomeClass !== "transient_failure";
364	    const poll = repeat && !reacquired && !stateUnknown && (outcomeClass === "transient_failure" || (kind === "external" && outcomeClass === "success"));
365	    // Only occurrences the model made while it still had the result count toward a loop.
366	    const loop = repeat && !reacquired && !stateUnknown && !poll && kind !== "bookkeeping" && record.count - (record.reacquired ?? 0) >= REPEAT_THRESHOLD;
367	    const thrash = reacquired && (record.reacquired ?? 0) >= REPEAT_THRESHOLD - 1;
368	    if (outcomeClass === "deterministic_failure" && record.count === 1) {
369	      this.event(this.data.failedApproaches, MAX_FAILED, step, o.name, `${record.action} -> ${record.outcome}`);
370	    }
371	    return { key, record, repeat, informative, loop, poll, stateUnknown, reacquired, thrash };
372	  }
373	
374	  /** Keeps records that show recurrence; evicts the oldest single-count record first. */
375	  private insertRepetition(record: RepetitionRecord): void {
376	    const list = this.data.repetitions;
377	    list.push(record);
378	    while (list.length > MAX_REPETITIONS) {
379	      const single = list.findIndex((r) => r.count <= 1 && r !== record);
380	      list.splice(single >= 0 ? single : 0, 1);
381	      this.data.evicted.repetitions++;
382	    }
383	  }
384	
385	  /**
386	   * The repetition record a call would add to, if it were re-run now on `state` with the same outcome as last time:
387	   * used to wait before re-running an unchanged poll or a transient failure.
388	   */
389	  priorRun(name: string, args: unknown, state: string): RepetitionRecord | undefined {
390	    if (state === "unknown") return undefined;
391	    const actionId = digest(actionIdentity(name, args));
392	    return this.data.repetitions.filter((r) => r.state === state && r.actionId === actionId).sort((a, b) => b.lastStep - a.lastStep)[0];
393	  }
394	
395	  /** Judges a finished step. */
396	  evaluateStep(step: number, input: {
397	    stateBefore: string;
398	    stateAfter: string;
399	    verdicts: ObservationVerdict[];
400	    ledgerState?: string;
401	    operatorInput?: boolean;
402	  }): StepEvaluation {
403	    const reasons: string[] = [];
404	    const stateUnknown = input.stateAfter === "unknown" || input.stateBefore === "unknown";
405	    if (input.stateAfter !== "unknown") {
406	      const isNew = addSeen(this.data.seenStates, input.stateAfter, (n) => (this.data.evicted.states += n));
407	      if (isNew && input.stateAfter !== input.stateBefore && input.stateBefore !== "") reasons.push("workspace reached a new state");
408	    }
409	    if (input.verdicts.some((v) => v.informative)) reasons.push("new information observed");
410	    if (input.ledgerState && addSeen(this.data.seenLedgerStates, input.ledgerState, (n) => (this.data.evicted.ledgerStates += n)) && this.data.seenLedgerStates.length > 1) {
411	      reasons.push("acceptance ledger changed");
412	    }
413	    if (input.operatorInput) reasons.push("operator input applied");
414	    if (stateUnknown) {
415	      const distinctMutation = input.verdicts.some((v) => {
416	        if (v.record.actionKind !== "mutate" || v.record.outcomeClass !== "success") return false;
417	        if (v.record.count > 1) return false;
418	        return !this.data.repetitions.some((r) => r !== v.record && r.actionId === v.record.actionId);
419	      });
420	      if (distinctMutation) reasons.push("distinct workspace mutation on unknown state");
421	    }
422	    const progressed = reasons.length > 0;
423	    if (progressed) {
424	      this.data.stepsWithoutProgress = 0;
425	      this.data.lastProgressStep = step;
426	      this.event(this.data.progress, MAX_EVENTS, step, "progress", reasons.join("; "));
427	    } else {
428	      this.data.stepsWithoutProgress++;
429	    }
430	    return { progressed, reasons, stateUnknown };
431	  }
432	
433	  /** Seeds the ledger-state set without counting it as progress (the state at the start of a turn). */
434	  noteLedgerState(ledgerState: string): void {
435	    addSeen(this.data.seenLedgerStates, ledgerState, (n) => (this.data.evicted.ledgerStates += n));
436	  }
437	
438	  noteState(state: string): void {
439	    if (state !== "unknown") addSeen(this.data.seenStates, state, (n) => (this.data.evicted.states += n));
440	  }
441	
442	  /** Operator input (a follow-up turn or steering) is new information: the no-progress run starts over. */
443	  operatorInput(step: number, detail: string): void {
444	    this.data.stepsWithoutProgress = 0;
445	    this.event(this.data.progress, MAX_EVENTS, step, "operator_input", detail);
446	  }
447	
448	  stagnation(step: number, kind: string, detail: string): void {
449	    this.event(this.data.stagnation, MAX_EVENTS, step, kind, detail);
450	  }
451	
452	  intervention(step: number, kind: string, detail: string): void {
453	    this.event(this.data.interventions, MAX_INTERVENTIONS, step, kind, detail);
454	  }
455	
456	  /**
457	   * Records a compaction. A pressure-triggered compaction (the request still fit) that freed less than
458	   * `lowYieldRatio` of the window is low-yield; consecutive low-yield compactions are thrashing evidence.
459	   */
460	  compaction(event: Omit<CompactionEvent, "at" | "lowYield">, window: number, pressureOnly: boolean, lowYieldRatio = 0.05): CompactionEvent {
461	    const freed = event.beforeTokens - event.afterTokens;
462	    const lowYield = pressureOnly && freed < window * lowYieldRatio;
463	    const record: CompactionEvent = { ...event, at: this.clock(), ...(lowYield ? { lowYield } : {}) };
464	    pushBounded(this.data.compactions, record, MAX_COMPACTIONS, (n) => (this.data.evicted.events += n));
465	    if (event.committed) this.data.lowYieldCompactions = lowYield ? this.data.lowYieldCompactions + 1 : 0;
466	    return record;
467	  }
468	
469	  /** Demonstrated loops (count >= threshold on a known state, re-acquisitions excluded), newest first. */
470	  loops(): RepetitionRecord[] {
471	    return this.data.repetitions.filter((r) => r.count - (r.reacquired ?? 0) >= REPEAT_THRESHOLD && r.state !== "unknown").sort((a, b) => b.lastStep - a.lastStep);
472	  }
473	
474	  /** Observations re-acquired after compaction removed them, most often first: context-thrash evidence. */
475	  reacquisitions(): RepetitionRecord[] {
476	    return this.data.repetitions.filter((r) => (r.reacquired ?? 0) > 0).sort((a, b) => (b.reacquired ?? 0) - (a.reacquired ?? 0));
477	  }
478	
479	  /** One-line summary for the pinned ledger and receipts. */
480	  summary(): string {
481	    const d = this.data;
482	    const loops = this.loops();
483	    const parts = [`${d.cumulativeSteps} steps over ${d.turns} turn(s)`];
484	    if (d.stepsWithoutProgress) parts.push(`${d.stepsWithoutProgress} step(s) since the last progress`);
485	    if (loops.length) parts.push(`repeated without progress: ${loops.slice(0, 3).map((r) => `${r.action} ×${r.count}`).join("; ")}`);
486	    if (d.failedApproaches.length) parts.push(`${d.failedApproaches.length} failed approach(es) recorded`);
487	    if (d.compactions.length) parts.push(`${d.compactions.filter((c) => c.committed).length} compaction(s)`);
488	    return parts.join("; ");
489	  }
490	}
